val old = historyList.firstOrNull { it.uri == uri }
historyList.removeAll { it.uri == uri }
historyList.add(0, HistoryItem(
    uri = uri, title = title, source = hint, time = System.currentTimeMillis(),
    thumbPath = old?.thumbPath, artworkPath = old?.artworkPath,
    positionMs = old?.positionMs ?: 0, durationMs = old?.durationMs ?: 0,
    artworkUrl = (artworkUrl ?: old?.artworkUrl)?.takeIf { it.isNotBlank() }
))

fun stop() {
    desiredPlaying = false
    pendingSeekMs = -1
    main.post { command?.onStop() }
}

val snapshot = cachedBmp.copy(cachedBmp.config ?: Bitmap.Config.ARGB_8888, false)
decodeExecutor.execute {
    Thumbnails.saveJpeg(snapshot, favFile)
    if (!snapshot.isRecycled) snapshot.recycle()
}
